<script setup lang="ts">
import {ref,computed} from 'vue';import PageShell from '../../components/PageShell.vue';import {useCartStore} from '../../store/modules/cart';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {go,money} from '../../utils/format'
const cart=useCartStore(),services=ref<any[]>([]);const {loading,error,load}=usePage(async()=>services.value=(await request('/public/catalog')).services);const total=computed(()=>services.value.reduce((sum,s)=>sum+Number(s.price)*(s.code==='BASE'?1:s.code==='EXTRA_PET'?Math.max(0,cart.petIds.length-1):cart.services.includes(s.id)?1:0),0));function toggle(id:number){cart.services=cart.services.includes(id)?cart.services.filter(x=>x!==id):[...cart.services,id]}
</script><template><PageShell title="照护要求" back :loading="loading" :error="error" @retry="load"><view class="steps"><text>01 选择服务</text><text class="on">02 照护要求</text><text>03 确认预约</text></view><view class="title">多一点，贴心照顾。</view><view class="section">附加服务 <text class="muted">可多选</text></view><view v-for="s in services.filter(x=>!['BASE','EXTRA_PET'].includes(x.code))" :key="s.id" :class="['option',{selected:cart.services.includes(s.id)}]" @click="toggle(s.id)"><view class="row"><view><view>{{s.name}}</view><text class="muted">{{s.description||'按次计费'}}</text></view><text class="link">＋{{money(s.price)}} {{cart.services.includes(s.id)?'✓':'＋'}}</text></view></view><view class="section">给喂养师的话</view><view class="field field-area"><textarea v-model="cart.notes" maxlength="1000" placeholder="猫粮位置、饮食禁忌、进门注意事项…请勿在备注里填写门锁密码。"/></view><view class="card"><view class="row"><text>服务预估合计</text><text class="amount">{{money(total)}}</text></view><text class="muted">含 {{cart.petIds.length}} 只宠物。会员与优惠券在确认订单时结算，以服务端计算为准。</text></view><button class="primary" @click="go('owner/agreement')">下一步 · 阅读上门授权 →</button></PageShell></template>
